21	/**
22	 * Base type for the "an owner just like this one already exists" conflicts raised while creating an
23	 * owner. Each subtype identifies a single uniqueness rule (telephone, household, ...) and carries the
24	 * two pieces of data the {@link ExceptionControllerAdvice} needs to render a uniform
25	 * {@code 409 Conflict}: a client-facing {@linkplain #getDetail() detail} message and the
26	 * {@linkplain #getErrorFields() names of the offending request fields}. Handling all of them through
27	 * this base keeps the advice to one handler, so a new uniqueness rule adds a subtype rather than
28	 * another near-identical handler.
29	 */
30	public abstract class DuplicateOwnerException extends RuntimeException {
31	
32	    private final String detail;
33	
34	    private final List<String> errorFields;
35	
36	    /**
37	     * @param message     the internal (log/diagnostic) message, typically naming the offending value
38	     * @param detail      the client-facing detail reported in the {@code 409 Conflict} response body
39	     * @param errorFields the names of the request fields that collided, reported in the response
40	     *                    {@code errors} array
41	     */
42	    protected DuplicateOwnerException(String message, String detail, List<String> errorFields) {
43	        super(message);
44	        this.detail = detail;
45	        this.errorFields = List.copyOf(errorFields);
