91	
92	    /**
93	     * Maximum number of owners that may be registered in a single day. A create made once this many
94	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
95	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
96	     */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /**
100	     * The number of owners that must already carry a given day's {@code registrationDate} before a
101	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
102	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
103	     */
104	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
105	
