110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        normalizeAddress(ownerFieldsDto);
153	        rejectBlankOwnerFields(ownerFieldsDto);
154	        normalizeTelephone(ownerFieldsDto);
155	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
156	        rejectDuplicateHousehold(ownerFieldsDto);
157	        rejectCityAtCapacity(ownerFieldsDto.getCity());
158	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
159	        long registeredThatDay = countRegisteredOn(registrationDate);
160	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
161	        normalizeEmail(ownerFieldsDto);
162	        HttpHeaders headers = new HttpHeaders();
163	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
164	        owner.setRegistrationDate(registrationDate);
165	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
166	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
167	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
168	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
169	        this.clinicService.saveOwner(owner);
170	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
171	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
190	        normalizeEmail(ownerFieldsDto);
191	        currentOwner.setEmail(ownerFieldsDto.getEmail());
192	        currentOwner.setHouseholdId(
193	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
194	        this.clinicService.saveOwner(currentOwner);
195	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Transactional
200	    @Override
201	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        this.clinicService.deleteOwner(owner);
207	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        HttpHeaders headers = new HttpHeaders();
218	        Pet pet = petMapper.toPet(petFieldsDto);
219	        owner.setId(ownerId);
220	        pet.setOwner(owner);
221	        pet.getType().setName(null);
222	        this.clinicService.savePet(pet);
223	        PetDto petDto = petMapper.toPetDto(pet);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
225	            .buildAndExpand(pet.getId()).toUri());
226	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner != null) {
234	            Pet currentPet = this.clinicService.findPetById(petId);
235	            if (currentPet != null) {
236	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
237	                currentPet.setName(petFieldsDto.getName());
238	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
239	                this.clinicService.savePet(currentPet);
240	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
249	        HttpHeaders headers = new HttpHeaders();
250	        Visit visit = visitMapper.toVisit(visitFieldsDto);
251	        Pet pet = new Pet();
252	        pet.setId(petId);
253	        visit.setPet(pet);
254	        this.clinicService.saveVisit(visit);
255	        VisitDto visitDto = visitMapper.toVisitDto(visit);
256	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
257	            .buildAndExpand(visit.getId()).toUri());
258	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
259	    }
260	
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
265	        Owner owner = this.clinicService.findOwnerById(ownerId);
266	        if (owner != null) {
267	            Pet pet = owner.getPet(petId);
268	            if (pet != null) {
269	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
270	            }
271	        }
272	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	    }
274	
275	    /**
276	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
277	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
278	     * the request body already rejects null and empty values, but permits whitespace-only strings
279	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
280	     * that gap so every required field must carry a non-blank value.
281	     *
282	     * @param ownerFieldsDto the submitted owner fields
283	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
284	     */
285	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
286	        List<String> missing = new ArrayList<>();
287	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
288	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
289	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
290	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
291	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
292	        if (!missing.isEmpty()) {
293	            throw new InvalidOwnerFieldsException(missing);
294	        }
295	    }
296	
297	    private void addIfBlank(List<String> missing, String fieldName, String value) {
298	        if (value == null || value.isBlank()) {
299	            missing.add(fieldName);
300	        }
301	    }
302	
303	    /**
304	     * Normalizes the submitted {@code address} on create to its canonical form (see
305	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
306	     * stored and returned, and the form every later address comparison (the required-field check,
307	     * household duplicate detection and the shared household id) is judged on. A null address is left
308	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
309	     * after normalization likewise reduces to the empty string and is rejected there.
310	     *
311	     * @param ownerFieldsDto the submitted owner fields
312	     */
313	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
314	        String address = ownerFieldsDto.getAddress();
315	        if (address == null) {
316	            return;
317	        }
318	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
319	    }
320	
321	    /**
322	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
323	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
324	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
325	     * {@code 400 Bad Request}.
326	     *
327	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
328	     *                       {@link #rejectBlankOwnerFields} having already run)
329	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
330	     */
331	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
332	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
333	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
334	        ownerFieldsDto.setTelephone(normalized);
335	    }
336	
337	    /**
338	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
339	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
340	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
341	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
342	     *
343	     * @param ownerFieldsDto the submitted owner fields
344	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
345	     */
346	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
347	        String email = ownerFieldsDto.getEmail();
348	        if (email == null || email.isBlank()) {
349	            return;
350	        }
351	        email = email.trim();
352	        if (!EMAIL_PATTERN.matcher(email).matches()) {
353	            throw new InvalidOwnerFieldsException(List.of("email"));
354	        }
355	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
356	    }
357	
358	    /**
359	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
360	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
361	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
362	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
363	     *
364	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
365	     *                            {@link #normalizeTelephone}
366	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
367	     */
368	    private void rejectDuplicateTelephone(String normalizedTelephone) {
369	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
370	        boolean inUse = this.clinicService.findAllOwners().stream()
371	            .map(Owner::getTelephone)
372	            .filter(Objects::nonNull)
373	            .map(TelephoneNormalizer::toComparisonKey)
374	            .anyMatch(comparisonKey::equals);
375	        if (inUse) {
376	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
377	        }
378	    }
379	
380	    /**
381	     * Rejects creating an owner who shares a household with any existing owner, unless the request
382	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
383	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
384	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
385	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
386	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
387	     *
388	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
389	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
390	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
391	     *                                          request did not opt in with {@code sharesHousehold}
392	     */
393	    /**
394	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
395	     * both match the submitted values, compared case-insensitively. The count reflects only owners
396	     * already persisted at the time of the create, so the owner being created is never included.
397	     *
398	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
399	     *                  having already run)
400	     * @param lastName  the submitted last name (non-blank here)
401	     * @return the number of existing owners sharing the same first and last name
402	     */
403	    private int countNamesakes(String firstName, String lastName) {
404	        return (int) this.clinicService.findAllOwners().stream()
405	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
406	                && lastName.equalsIgnoreCase(owner.getLastName()))
407	            .count();
408	    }
409	
410	    /**
411	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
412	     * whose stored {@code householdId} equals the value derived for the owner being created. The
413	     * count reflects only owners already persisted at the time of the create, so the owner being
414	     * created is never included; callers add one to obtain the household size after this create.
415	     *
416	     * @param householdId the household identifier derived for the owner being created (see
417	     *                    {@link HouseholdNormalizer#toHouseholdId})
418	     * @return the number of existing owners already sharing that household
419	     */
420	    private int countHouseholdMembers(String householdId) {
421	        if (householdId == null) {
422	            return 0;
423	        }
424	        return (int) this.clinicService.findAllOwners().stream()
425	            .map(Owner::getHouseholdId)
426	            .filter(householdId::equals)
427	            .count();
428	    }
429	
430	    /**
431	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
432	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
433	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
434	     *
435	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
436	     *             run)
437	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
438	     */
439	    private void rejectCityAtCapacity(String city) {
440	        long ownersInCity = this.clinicService.findAllOwners().stream()
441	            .map(Owner::getCity)
442	            .filter(Objects::nonNull)
443	            .filter(city::equalsIgnoreCase)
444	            .count();
445	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
446	            throw new OwnerCityAtCapacityException(city);
447	        }
448	    }
449	
450	    /**
451	     * Resolves the effective registration date for a create, rolled onto a business day. The
452	     * supplied date is used when present, otherwise the server's current date; either way the result
453	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
454	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
455	     * stored {@code registrationDate}, the membership number's year segment and the daily
456	     * create-limit's per-day count - is judged on this adjusted date.
457	     *
458	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
459	     *                                 default to the server's current date
460	     * @return the effective registration date, guaranteed to fall on a business day
461	     */
462	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
463	        LocalDate registrationDate =
464	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
465	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
466	    }
467	
468	    /**
469	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
470	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
471	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
472	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
473	     * Too Many Requests}.
474	     *
475	     * @param registrationDate   the create's effective registration date, already rolled onto a
476	     *                           business day by {@link #effectiveRegistrationDate}
477	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
478	     *                           {@code registrationDate} equals {@code registrationDate}
479	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
480	     *                                              owner registrations
481	     */
482	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
483	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
484	            throw new OwnerDailyRegistrationLimitException(registrationDate);
485	        }
486	    }
487	
488	    /**
489	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
490	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
491	     * bulk-signup warning are judged on.
492	     *
493	     * @param registrationDate the create's effective registration date, already rolled onto a business
494	     *                         day by {@link #effectiveRegistrationDate}
495	     * @return the number of existing owners registered on that day
496	     */
497	    private long countRegisteredOn(LocalDate registrationDate) {
498	        return this.clinicService.findAllOwners().stream()
499	            .map(Owner::getRegistrationDate)
500	            .filter(registrationDate::equals)
501	            .count();
502	    }
503	
504	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
505	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
506	            return;
507	        }
508	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
509	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
510	        boolean inUse = this.clinicService.findAllOwners().stream()
511	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
512	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
513	            .anyMatch(comparisonKey::equals);
514	        if (inUse) {
515	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
516	        }
517	    }
518	}
